import {
  afterNextRender,
  ChangeDetectionStrategy,
  Component,
  ElementRef,
  inject,
} from '@angular/core';

/**
 * jh-route-map: the Sunday pickup run from the Wesleyan pickup spots to the
 * red doors on Washington Street. Decorative schematic (the copy beside it
 * carries the facts); the SVG is generated by art-src/scenes/route.py.
 * The car drives the route on a loop (SMIL). Under prefers-reduced-motion it
 * is paused, parked at the doors.
 */
@Component({
  selector: 'app-route-map',
  changeDetection: ChangeDetectionStrategy.OnPush,
  templateUrl: './route-map.html',
  styles: `
    :host {
      display: block;
    }
    .route-map {
      display: block;
      width: 100%;
      height: 100%;
    }
    .route-map__pin {
      font: 700 13px var(--font-body);
      fill: var(--color-jh-ink);
    }
    .route-map__place {
      font: 600 15px var(--font-display);
      fill: var(--color-jh-blue);
    }
    .route-map__street {
      font: 700 10.5px var(--font-body);
      fill: var(--color-jh-gold-ink);
    }
    .route-map__area {
      font: italic 600 15px var(--font-display);
      fill: #3f6650;
    }
  `,
})
export class RouteMap {
  private readonly host = inject<ElementRef<HTMLElement>>(ElementRef);

  constructor() {
    afterNextRender(() => {
      if (!window.matchMedia('(prefers-reduced-motion: reduce)').matches) return;
      const svg = this.host.nativeElement.querySelector('svg');
      svg?.pauseAnimations();
      svg?.setCurrentTime(7.2);
    });
  }
}
